{
  "headline": "Ceftriaxone sodium is not on FDA's shortage list as of 2026-10-21; supply at Corvale Lakeside is 8.8 days on hand for the 1 g injection",
  "headline_cites": ["D5", "D3"],
  "sentences": [
    {
      "text": "FDA's drug shortage list shows ceftriaxone sodium is not listed as of 2026-10-21.",
      "cites": ["D5"]
    },
    {
      "text": "Corvale Lakeside holds 37 vials of the 1 g injection with daily use of 4.2 vials, giving 8.8 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "Corvale East holds 253 vials of the same 1 g injection with daily use of 12.9 vials, giving 19.6 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale General holds 298 vials of the 1 g injection with daily use of 15.8 vials, giving 18.9 days on hand.",
      "cites": ["D2"]
    },
    {
      "text": "The top-ranked option by rule is to transfer 22 vials of 1 g from Corvale East to Corvale Lakeside, which would leave Corvale East with 18 days and bring Corvale Lakeside to 14 days.",
      "cites": ["D6"]
    },
    {
      "text": "All three Corvale sites use product labeled by REMEDYREPACK INC. (NDC 70518249900) whose SPL set identifies the manufacturer as SANDOZ.",
      "cites": ["E1", "E3", "E4", "E5"]
    },
    {
      "text": "An alternate manufacturer option from Civica, Inc. cites Hikma Farmacêutica (Portugal) as the plant, but the drug is not on FDA's shortage list today.",
      "cites": ["D8"]
    }
  ]
}
